/*
 * A169556  Number of reduced words of length n in Coxeter group on 15
 *          generators S_i with relations (S_i)^2 = (S_i S_j)^35 = I.
 * https://oeis.org/A169556
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(0) = 1 For 1 ≤ n ≤ 34: a(n) = 2 + 13 * Σ_{i=0}^{n-1} a(i) For
 *            n ≥ 35: a(n) = 13 * Σ_{i=n-34}^{n-1} a(i) – 91 * a(n-35)
 *            (Generated by the rational generating function (t^35 + 2*t^34 +
 *            … + 2*t + 1) / (91*t^35 – 13*t^34 – … – 13*t + 1))
 * Range:     u8 n <= 2, u16 n <= 4, u32 n <= 8, u64 n <= 16, u128 n <= 16,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>

/* Dynamic arrays to store the sequence and its prefix sums. */
static seq_t *a_cache    = NULL;
static seq_t *pref_cache = NULL;
static size_t cache_cap   = 0;   /* allocated capacity */
static size_t cache_len   = 0;   /* number of terms currently computed */

/* Return the n-th term of A169556.  The result is memoised. */
seq_t a(idx_t n)
{
    /* 1. Ensure sufficient capacity for the required index. */
    if ((size_t)n >= cache_cap) {
        size_t new_cap = cache_cap ? cache_cap * 2 : 16;
        while ((size_t)n >= new_cap)
            new_cap <<= 1;
        seq_t *new_a    = (seq_t *)realloc(a_cache,    new_cap * sizeof(seq_t));
        seq_t *new_pref = (seq_t *)realloc(pref_cache, new_cap * sizeof(seq_t));
        if (!new_a || !new_pref) {
            /* Allocation failed – return zero (sequence values are all positive). */
            if (new_a) free(new_a);
            if (new_pref) free(new_pref);
            return (seq_t)0;
        }
        a_cache    = new_a;
        pref_cache = new_pref;
        cache_cap  = new_cap;
    }

    /* 2. Compute any missing terms up to index n (inclusive). */
    for (idx_t k = cache_len; k <= n; ++k) {
        if (k == 0) {                       /* a(0) = 1 */
            a_cache[0]   = (seq_t)1;
            pref_cache[0] = (seq_t)1;
            continue;
        }
        if (k <= 34) {                      /* 1 ≤ k ≤ 34 */
            seq_t sum_prev = pref_cache[k - 1];
            a_cache[k]   = (seq_t)2 + (seq_t)13 * sum_prev;
            pref_cache[k] = pref_cache[k - 1] + a_cache[k];
        } else {                            /* k ≥ 35 */
            idx_t l = k - 34;               /* inclusive lower bound of the last 34 terms */
            seq_t window_sum = pref_cache[k - 1];
            if (l > 0)
                window_sum -= pref_cache[l - 1];
            a_cache[k] = (seq_t)13 * window_sum - (seq_t)91 * a_cache[k - 35];
            pref_cache[k] = pref_cache[k - 1] + a_cache[k];
        }
    }
    cache_len = (size_t)n + 1;

    /* 3. Return the requested term. */
    return a_cache[n];
}
